using System.Collections.Generic;
using UnityEngine;
namespace Podz {
    /// <summary>Игровой −2: каменные городские руины по слайду 15. Не используется на других этажах.</summary>
    public static class OvergrownRuins {
        public static readonly string[] Names={"Стартовый двор","Сад мандрагор","Заросшая улица","Курятник василиска","Зал колонн","Обрушенный храм","Колодец","Лестница спуска"};
        public static readonly int[] Types={0,1,3,2,6,5,4,7};
        static readonly Vector2Int[] Cells={new Vector2Int(0,0),new Vector2Int(0,1),new Vector2Int(1,1),new Vector2Int(2,1),new Vector2Int(0,2),new Vector2Int(1,2),new Vector2Int(2,2),new Vector2Int(2,3)};
        static readonly Vector2[] Sizes={new Vector2(11,10),new Vector2(12,11),new Vector2(16,7),new Vector2(12,12),new Vector2(13,13),new Vector2(13,12),new Vector2(10,11),new Vector2(11,12)};
        static readonly int[,] Links={{0,1},{1,2},{2,3},{1,4},{4,5},{5,6},{3,6},{6,7}};
        static FloorLayout _layout;static readonly List<Vector3> Reserved=new List<Vector3>();
        static Material _stone,_earth,_green,_moss,_wood,_crystal,_water;
        public static Material Stone {get{if(_stone==null)_stone=Surface("AgedWarmLimestone",new Color(.63f,.59f,.46f),.25f,true);return _stone;}}
        public static Material Earth {get{if(_earth==null)_earth=Surface("SoftBrownEarth",new Color(.31f,.245f,.15f),.08f,true);return _earth;}}
        static Material Green {get{if(_green==null){_green=Surface("OliveFoliage",new Color(.26f,.39f,.15f),.12f);_green.SetFloat("_Cull",0);}return _green;}}
        static Material Moss {get{if(_moss==null){_moss=Surface("RuinsMoss",new Color(.28f,.39f,.13f),.13f);_moss.SetFloat("_Cull",0);}return _moss;}}
        static Material Wood {get{if(_wood==null)_wood=Surface("NaturalBrownRoots",new Color(.28f,.20f,.10f),.13f,true);return _wood;}}
        public static Material Water {get{if(_water==null){_water=Surface("RuinsWellWater",new Color(.23f,.35f,.29f),.48f);_water.EnableKeyword("_EMISSION");_water.SetColor("_EmissionColor",new Color(.016f,.029f,.022f));}return _water;}}
        static Material Surface(string name,Color c,float smooth,bool texture=false){var m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.name=name;m.SetColor("_BaseColor",c);m.SetFloat("_Smoothness",smooth);m.enableInstancing=true;if(texture){const int n=128;var tex=new Texture2D(n,n,TextureFormat.RGB24,true){name=name+"Albedo",wrapMode=TextureWrapMode.Repeat};for(int y=0;y<n;y++)for(int x=0;x<n;x++){float v=.63f+.22f*Mathf.PerlinNoise(x*.07f,y*.08f)+.12f*Mathf.PerlinNoise(x*.3f,y*.3f);tex.SetPixel(x,y,new Color(v,v,v));}tex.Apply();m.SetTexture("_BaseMap",tex);}return m;}
        public static void Reserve(Vector3 p){Reserved.Add(p);}
        public static bool Free(Vector3 p,int ri,float margin=1.5f){if(_layout==null || ri<0 || ri>=8)return false;var r=_layout.Rooms[ri];var v=p-r.center;if(Mathf.Abs(v.x)>r.extents.x-margin || Mathf.Abs(v.z)>r.extents.z-margin)return false;
            if(ri==7 && v.z>-.3f && Mathf.Abs(v.x)<2.1f)return false;
            foreach(var q in Reserved){var d=p-q;d.y=0;if(d.sqrMagnitude<4f)return false;}return true;}
        static bool Clear(Vector3 p,int ri,float radius=.5f)=>Free(p,ri) && !Physics.CheckSphere(p+Vector3.up*(radius+.11f),radius,~0,QueryTriggerInteraction.Ignore);
        public static Vector3 Point(int ri){var r=_layout.Rooms[ri];for(int k=0;k<60;k++){var p=new Vector3(Random.Range(r.min.x+1.3f,r.max.x-1.3f),_layout.Origin.y,Random.Range(r.min.z+1.3f,r.max.z-1.3f));if(Clear(p,ri))return p;}
            for(float x=r.min.x+1.3f;x<r.max.x-1.3f;x+=.6f)for(float z=r.min.z+1.3f;z<r.max.z-1.3f;z+=.6f){var p=new Vector3(x,_layout.Origin.y,z);if(Clear(p,ri))return p;}return new Vector3(_layout.Rooms[0].center.x,_layout.Origin.y,_layout.Rooms[0].center.z);}
        public static Vector3 SafeDrop(Vector3 pos){if(_layout==null)return pos;int ri=0;float nearest=float.MaxValue;for(int i=0;i<8;i++){var v=pos-_layout.Rooms[i].center;v.y=0;if(v.sqrMagnitude<nearest){nearest=v.sqrMagnitude;ri=i;}}var p=new Vector3(pos.x,_layout.Origin.y,pos.z);if(Clear(p,ri,.18f))return pos;for(int k=1;k<7;k++)for(int j=0;j<12;j++){float a=j*Mathf.PI/6;var q=p+new Vector3(Mathf.Cos(a),0,Mathf.Sin(a))*k*.45f;if(Clear(q,ri,.18f)){q.y=pos.y;return q;}}var fallback=Point(ri);fallback.y=pos.y;return fallback;}
#if UNITY_EDITOR
        public static void DescribeBlocksForEditor(DungeonSourcePlan plan) {
            for(int i=0;i<8;i++){plan.Rooms.Add(new Bounds(new Vector3(Cells[i].x*20,2,Cells[i].y*20),new Vector3(Sizes[i].x,4,Sizes[i].y)));plan.RoomTypes.Add(Types[i]);}
            for(int k=0;k<8;k++){plan.Edges.Add(new Vector2Int(Links[k,0],Links[k,1]));}
        }
        public static void BuildRoomForEditor(Transform root,int index) {
            if(Application.isPlaying || index<0 || index>=8 || root.childCount!=0)throw new System.InvalidOperationException("Нужна пустая Editor-заготовка и индекс 0–7.");
            var exits=new List<Vector3>();
            for(int k=0;k<8;k++){int a=Links[k,0],b=Links[k,1];if(a==index || b==index){var d=Cells[a==index?b:a]-Cells[index];exits.Add(new Vector3(d.x,0,d.y).normalized);}}
            Room(root,Sizes[index],exits,index);Decor(root,Sizes[index],index);
        }
        public static void BuildPassageForEditor(Transform root,float length,int sourceIndex) {
            if(Application.isPlaying || root.childCount!=0 || length<=0)throw new System.InvalidOperationException("Нужна пустая Editor-заготовка коридора.");
            Passage(root,Vector3.back*length*.5f,Vector3.forward*length*.5f,sourceIndex);
        }
#endif
        public static FloorLayout Build(Transform root,Vector3 origin){Reserved.Clear();var L=new FloorLayout{Origin=origin,Start=0,Stairs=7,TransitionForward=Vector3.forward};_layout=L;
            for(int i=0;i<8;i++){L.Cells.Add(Cells[i]);L.Depth.Add(new[]{0,1,2,3,2,3,4,5}[i]);L.Rooms.Add(new Bounds(origin+new Vector3(Cells[i].x*20,2,Cells[i].y*20),new Vector3(Sizes[i].x,4,Sizes[i].y)));}
            L.TransitionEntrance=new Vector3(L.Rooms[7].center.x,origin.y,L.Rooms[7].min.z);
            if(SavedDungeonAssets.TryBuildFixed(SavedDungeonAssets.Active?.Ruins,2,root,L,Links))return L;
            for(int i=0;i<8;i++){var t=Node("RuinsRoom_"+i+"_"+Names[i],root,Vector3.zero);t.position=new Vector3(L.Rooms[i].center.x,origin.y,L.Rooms[i].center.z);var exits=new List<Vector3>();for(int k=0;k<8;k++){int a=Links[k,0],b=Links[k,1];if(a==i || b==i)exits.Add((L.Rooms[a==i?b:a].center-L.Rooms[i].center).normalized);}Room(t,Sizes[i],exits,i);Decor(t,Sizes[i],i);}
            for(int k=0;k<8;k++){int a=Links[k,0],b=Links[k,1];var d=L.Rooms[b].center-L.Rooms[a].center;d.y=0;d.Normalize();float ah=Mathf.Abs(d.x)>.5f?L.Rooms[a].extents.x:L.Rooms[a].extents.z,bh=Mathf.Abs(d.x)>.5f?L.Rooms[b].extents.x:L.Rooms[b].extents.z;var p=L.Rooms[a].center+d*ah;var q=L.Rooms[b].center-d*bh;p.y=q.y=origin.y;Passage(root,p,q,k);}
            Physics.SyncTransforms();return L;}
        static Transform Node(string name,Transform parent,Vector3 p){var t=new GameObject(name).transform;t.SetParent(parent,false);t.localPosition=p;return t;}
        public static GameObject Box(string name,Transform root,Vector3 p,Vector3 size,Material mat,bool solid=true){var g=Prim.Cube(name,root,p,size,Color.white,solid);g.GetComponent<Renderer>().sharedMaterial=mat;g.GetComponent<Renderer>().SetPropertyBlock(null);return g;}
        static GameObject Mesh(string name,Transform root,List<Vector3> v,List<int> tr,Material mat,bool solid=false){var g=CavePrototype.MeshObject(name,root,v,tr,mat,solid);var uv=new List<Vector2>();foreach(var p in v)uv.Add(new Vector2(p.x*.6f+p.z*.33f,p.y*.7f+p.z*.33f));g.GetComponent<MeshFilter>().sharedMesh.SetUVs(0,uv);return g;}
        static void Quad(List<Vector3> v,List<int> tr,Vector3 a,Vector3 b,Vector3 c,Vector3 d){int k=v.Count;v.Add(a);v.Add(b);v.Add(c);v.Add(d);tr.AddRange(new[]{k,k+1,k+2,k,k+2,k+3});}
        static void BoxMesh(List<Vector3> v,List<int> tr,Vector3 p,Vector3 size){var h=size*.5f;Vector3 P(float x,float y,float z)=>p+Vector3.Scale(h,new Vector3(x,y,z));Quad(v,tr,P(-1,-1,1),P(1,-1,1),P(1,1,1),P(-1,1,1));Quad(v,tr,P(1,-1,-1),P(-1,-1,-1),P(-1,1,-1),P(1,1,-1));Quad(v,tr,P(1,-1,1),P(1,-1,-1),P(1,1,-1),P(1,1,1));Quad(v,tr,P(-1,-1,-1),P(-1,-1,1),P(-1,1,1),P(-1,1,-1));Quad(v,tr,P(-1,1,1),P(1,1,1),P(1,1,-1),P(-1,1,-1));Quad(v,tr,P(-1,-1,-1),P(1,-1,-1),P(1,-1,1),P(-1,-1,1));}
        static float DoorHeight(float x)=>2.05f+.85f*Mathf.Sqrt(Mathf.Max(0,1-x*x/2.1025f));
        static Vector3 SidePoint(int side,float c,float y,float wx,float dz)=>side==0?new Vector3(c,y,dz):side==1?new Vector3(wx,y,-c):side==2?new Vector3(-c,y,-dz):new Vector3(-wx,y,c);
        static float Top(int side,float c,float wx)=>side%2==0?3f+1.55f*Mathf.Sqrt(Mathf.Max(0,1-c*c/(wx*wx))):3f;
        static void Room(Transform t,Vector2 size,List<Vector3> exits,int seed){float wx=size.x*.5f,dz=size.y*.5f;Box("EarthAndStoneFoundation",t,new Vector3(0,-.1f,0),new Vector3(size.x,.2f,size.y),Earth);
            var blockV=new List<Vector3>();var blockT=new List<int>();var wallV=new List<Vector3>();var wallT=new List<int>();Vector3[] normals={Vector3.forward,Vector3.right,Vector3.back,Vector3.left};
            for(int s=0;s<4;s++){float half=s%2==0?wx:dz;bool door=false;foreach(var d in exits)if(Vector3.Dot(d,normals[s])>.9f)door=true;
                var coords=new List<float>{-half,-1.45f,-.725f,0,.725f,1.45f,half};for(float c=-half+.7f;c<half;c+=.7f)if(Mathf.Abs(c)>1.45f)coords.Add(c);coords.Sort();
                for(int j=0;j<coords.Count-1;j++){float a=coords[j],b=coords[j+1];bool hole=door && Mathf.Abs((a+b)*.5f)<1.45f;float ya=hole?DoorHeight(a):0,yb=hole?DoorHeight(b):0;Quad(wallV,wallT,SidePoint(s,a,ya,wx,dz),SidePoint(s,a,Top(s,a,wx),wx,dz),SidePoint(s,b,Top(s,b,wx),wx,dz),SidePoint(s,b,yb,wx,dz));}
                for(int row=0;row<11;row++){float y=row*.42f+.21f;for(float c=-half+.42f+(row%2)*.42f;c<half-.1f;c+=.85f){if(door && Mathf.Abs(c)<1.9f && y<3.1f)continue;float top=Top(s,c,wx);if(y-.2f>=top)continue;float h=Mathf.Min(.40f,top-(y-.2f));var at=SidePoint(s,c,y-.2f+h*.5f,wx,dz)-normals[s]*.045f;var scale=s%2==0?new Vector3(.81f,h,.22f):new Vector3(.22f,h,.81f);BoxMesh(blockV,blockT,at,scale);}}
            }
            Mesh("SolidMasonryWalls",t,wallV,wallT,Stone,true);Mesh("MergedAgedStoneCourses",t,blockV,blockT,Stone);
            var rv=new List<Vector3>();var rt=new List<int>();const int n=25;for(int ring=0;ring<3;ring++)for(int j=0;j<n;j++){float a=j*Mathf.PI/(n-1);rv.Add(new Vector3(-Mathf.Cos(a)*wx,3+Mathf.Sin(a)*1.55f,(ring-1)*dz));}for(int ring=0;ring<2;ring++)for(int j=0;j<n-1;j++){int k=ring*n+j;rt.AddRange(new[]{k,k+1,k+n,k+1,k+n+1,k+n});}Mesh("ClosedStoneBarrelVault",t,rv,rt,Stone,true);
            // Рёбра древнего свода из небольших камней, объединённых в один меш.
            var ribV=new List<Vector3>();var ribT=new List<int>();for(int ring=0;ring<3;ring++)for(int j=1;j<18;j++){float a=j*Mathf.PI/18;BoxMesh(ribV,ribT,new Vector3(-Mathf.Cos(a)*(wx-.12f),Top(0,-Mathf.Cos(a)*(wx-.12f),wx)-.06f,(ring-1)*dz*.82f),new Vector3(.33f,.24f,.28f));}Mesh("AncientVaultRibs",t,ribV,ribT,Stone);
            foreach(var d in exits)Arch(t,d*(Mathf.Abs(d.x)>.5f?wx-.07f:dz-.07f),d);
            Paving(t,size,seed);for(int side=-1;side<=1;side+=2){var p=new Vector3(side*(wx-1.0f),0,-dz*.4f);CrystalCluster(t,p,seed+side);Prim.PointLight(t,p+Vector3.up*.8f,new Color(.92f,.78f,.41f),8f,2.8f);}
        }
        static void Paving(Transform t,Vector2 size,int seed){var v=new List<Vector3>();var tr=new List<int>();for(int x=0;x<(int)(size.x/.9f);x++)for(int z=0;z<(int)(size.y/1.1f);z++){float px=-size.x*.5f+.6f+x*.9f,pz=-size.y*.5f+.65f+z*1.1f;if((x+z+seed)%5==0)continue;if(seed==1 && Mathf.Abs(px)>1.6f)continue;float dx=.40f+.025f*Mathf.Sin(x+seed),dz=.47f;Quad(v,tr,new Vector3(px-dx,.013f,pz-dz),new Vector3(px-dx,.013f,pz+dz),new Vector3(px+dx,.013f,pz+dz),new Vector3(px+dx,.013f,pz-dz));}Mesh("BrokenPavingOverSoftEarth",t,v,tr,Stone);}
        static void Arch(Transform root,Vector3 p,Vector3 forward){var t=Node("OldMasonryArch",root,p);t.localRotation=Quaternion.LookRotation(forward);var v=new List<Vector3>();var tr=new List<int>();for(int side=-1;side<=1;side+=2)for(int j=0;j<5;j++)BoxMesh(v,tr,new Vector3(side*1.65f,j*.39f+.195f,0),new Vector3(.38f,.37f,.38f));for(int j=0;j<15;j++){float a=j*Mathf.PI/14;BoxMesh(v,tr,new Vector3(Mathf.Cos(a)*1.65f,1.92f+Mathf.Sin(a)*.94f,0),new Vector3(.32f,.30f,.42f));}Mesh("ArchVoussoirs",t,v,tr,Stone);Vine(t,new Vector3(-1.65f,1.92f,-.23f),1.8f,7);Vine(t,new Vector3(1.65f,1.7f,-.23f),1.6f,8);}
        static void Passage(Transform root,Vector3 p,Vector3 q,int seed){var t=Node("RuinsPassage_"+seed,root,Vector3.zero);t.position=(p+q)*.5f;t.rotation=Quaternion.LookRotation(q-p);float len=Vector3.Distance(p,q)+.16f;var v=new List<Vector3>();var tr=new List<int>();const int n=13;for(int ring=0;ring<2;ring++)for(int j=0;j<n;j++){float x=j==0?-1.45f:j==n-1?1.45f:-1.45f+(j-1)*2.9f/10;v.Add(new Vector3(x,j==0 || j==n-1?0:DoorHeight(x),(ring==0?-1:1)*len*.5f));}for(int j=0;j<n-1;j++)tr.AddRange(new[]{j,j+1,j+n,j+1,j+1+n,j+n});Mesh("PassageArchAndWalls",t,v,tr,Stone,true);Box("PassagePaving",t,new Vector3(0,-.1f,0),new Vector3(2.95f,.2f,len),Stone);Prim.PointLight(t,new Vector3(0,2,0),new Color(.84f,.77f,.48f),7f,1.9f);}
        static void Patch(Transform t,Vector3 p,Vector3 normal,float radius,int seed,Material mat){var v=new List<Vector3>{Vector3.zero};var tr=new List<int>();for(int j=0;j<20;j++){float a=j*Mathf.PI/10,r=radius*(1+.16f*Mathf.Sin(j*1.9f+seed));v.Add(new Vector3(Mathf.Cos(a)*r,Mathf.Sin(a)*r*.5f,0));}for(int j=0;j<20;j++)tr.AddRange(new[]{0,j+1,(j+1)%20+1});var g=Mesh("IrregularMossPatch",t,v,tr,mat);g.transform.localPosition=p;g.transform.localRotation=Quaternion.FromToRotation(Vector3.forward,normal);}
        static void Leaf(List<Vector3> v,List<int> tr,Vector3 p,Vector3 direction,float width){var side=Vector3.Cross(direction.normalized,Vector3.up);if(side.sqrMagnitude<.01f)side=Vector3.right;side=side.normalized*width;int k=v.Count;v.Add(p);v.Add(p+direction*.43f-side);v.Add(p+direction);v.Add(p+direction*.43f+side);tr.AddRange(new[]{k,k+1,k+2,k,k+2,k+3});}
        static void Plant(Transform t,Vector3 p,int seed,bool flowers=false){var v=new List<Vector3>();var tr=new List<int>();for(int j=0;j<8;j++){float a=j*Mathf.PI/4+seed;Leaf(v,tr,p,new Vector3(Mathf.Cos(a)*.34f,.3f+(j%3)*.09f,Mathf.Sin(a)*.34f),.07f);}Mesh("BroadGroundLeaves",t,v,tr,Green);if(flowers){var petalV=new List<Vector3>();var petalT=new List<int>();for(int j=0;j<3;j++){var c=p+new Vector3((j-1)*.12f,.22f+(j%2)*.10f,.05f);for(int k=0;k<5;k++){float a=k*Mathf.PI*2/5;Leaf(petalV,petalT,c,new Vector3(Mathf.Cos(a)*.085f,.015f,Mathf.Sin(a)*.085f),.035f);}}if(_crystal==null)_crystal=Surface("WarmOchreCrystal",new Color(.76f,.62f,.29f),.32f);Mesh("SmallOchreFlowers",t,petalV,petalT,_crystal);}}
        static void Tube(Transform t,string name,List<Vector3> path,float radius,Material mat){var v=new List<Vector3>();var tr=new List<int>();const int n=7;for(int k=0;k<path.Count;k++){var dir=k==path.Count-1?path[k]-path[k-1]:path[k+1]-path[k];var q=Quaternion.FromToRotation(Vector3.up,dir.normalized);for(int j=0;j<n;j++){float a=j*Mathf.PI*2/n;v.Add(path[k]+q*new Vector3(Mathf.Cos(a)*radius,0,Mathf.Sin(a)*radius));}}for(int k=0;k<path.Count-1;k++)for(int j=0;j<n;j++){int a=k*n+j,b=k*n+(j+1)%n;tr.AddRange(new[]{a,a+n,b,b,a+n,b+n});}Mesh(name,t,v,tr,mat);}
        static void Vine(Transform t,Vector3 p,float length,int seed){var path=new List<Vector3>();var v=new List<Vector3>();var tr=new List<int>();for(int j=0;j<9;j++){float f=j/8f;var at=p+new Vector3(Mathf.Sin(f*3+seed)*.11f,-length*f,Mathf.Cos(f*3+seed)*.07f);path.Add(at);if(j>1)Leaf(v,tr,at,new Vector3((j%2==0?-1:1)*.17f,.08f,.035f),.045f);}Tube(t,"ClimbingVine",path,.025f,Wood);Mesh("VineLeaves",t,v,tr,Green);}
        static void TreeRoot(Transform t,Vector3 p,int seed){var path=new List<Vector3>();for(int j=0;j<8;j++)path.Add(p+new Vector3(Mathf.Sin(j*.45f+seed)*.24f,j*.47f,Mathf.Cos(j*.45f+seed)*.13f));float wallX=t.Find("SolidMasonryWalls").GetComponent<MeshFilter>().sharedMesh.bounds.extents.x;path.Add(new Vector3(Mathf.Sign(p.x)*(wallX-.03f),3f,p.z+.1f));Tube(t,"ThickAttachedTreeRoot",path,.10f,Wood);for(int side=-1;side<=1;side+=2)Tube(t,"GroundRootBranch",new List<Vector3>{p+Vector3.up*.25f,p+new Vector3(side*.4f,.08f,.2f),p+new Vector3(side*.7f,.025f,.4f)},.045f,Wood);}
        static void CrystalCluster(Transform t,Vector3 p,int seed){if(_crystal==null){_crystal=Surface("WarmOchreCrystal",new Color(.76f,.62f,.29f),.32f);_crystal.EnableKeyword("_EMISSION");_crystal.SetColor("_EmissionColor",new Color(.12f,.08f,.018f));}var v=new List<Vector3>();var tr=new List<int>();for(int k=0;k<4;k++){var c=p+new Vector3((k-1.5f)*.18f,0,(k%2)*.12f);float h=.40f+(k%3)*.16f;int first=v.Count;for(int ring=0;ring<2;ring++)for(int j=0;j<6;j++){float a=j*Mathf.PI/3;v.Add(c+new Vector3(Mathf.Cos(a)*.11f,ring*h*.72f,Mathf.Sin(a)*.11f));}int tip=v.Count;v.Add(c+new Vector3(.025f,h,0));for(int j=0;j<6;j++){int a=first+j,b=first+(j+1)%6;tr.AddRange(new[]{a,a+6,b,b,a+6,b+6,a+6,tip,b+6});}}Mesh("WarmCrystalCluster",t,v,tr,_crystal);}
        static void Column(Transform t,Vector3 p,float height){var v=new List<Vector3>();var tr=new List<int>();const int n=12;for(int ring=0;ring<5;ring++)for(int j=0;j<n;j++){float a=j*Mathf.PI*2/n,r=ring==0 || ring==4?.52f:.36f;v.Add(p+new Vector3(Mathf.Cos(a)*r,height*ring/4f,Mathf.Sin(a)*r));}for(int ring=0;ring<4;ring++)for(int j=0;j<n;j++){int a=ring*n+j,b=ring*n+(j+1)%n;tr.AddRange(new[]{a,a+n,b,b,a+n,b+n});}int topCenter=v.Count;v.Add(p+Vector3.up*height);for(int j=0;j<n;j++)tr.AddRange(new[]{topCenter,4*n+(j+1)%n,4*n+j});Mesh("WeatheredStoneColumn",t,v,tr,Stone);var solid=Node("ColumnCollision",t,p+Vector3.up*height*.5f).gameObject;solid.AddComponent<BoxCollider>().size=new Vector3(.85f,height,.85f);Patch(t,p+new Vector3(0,height*.4f,.37f),Vector3.forward,.55f,3,Moss);Vine(t,p+new Vector3(.34f,height,.1f),height*.9f,7);}
        static void Statue(Transform t,Vector3 p,int pose){var r=Node("PetrifiedAdventurer",t,p);Box("StonePlinth",r,new Vector3(0,.12f,0),new Vector3(.75f,.24f,.7f),Stone);var torso=Prim.Sphere("HumanStatueTorso",r,new Vector3(0,.95f,0),new Vector3(.42f,.68f,.30f),Color.white);var head=Prim.Sphere("HumanStatueHead",r,new Vector3(0,1.46f,0),new Vector3(.27f,.32f,.25f),Color.white);foreach(var g in new[]{torso,head}){g.GetComponent<Renderer>().sharedMaterial=Stone;g.GetComponent<Renderer>().SetPropertyBlock(null);}for(int side=-1;side<=1;side+=2){var arm=Prim.Cyl("StatueArm",r,new Vector3(side*.3f,1.03f,.04f),new Vector3(.13f,.55f,.13f),Color.white,new Vector3(0,0,side*(pose==0?45:15)));arm.GetComponent<Renderer>().sharedMaterial=Stone;arm.GetComponent<Renderer>().SetPropertyBlock(null);var leg=Prim.Cyl("StatueLeg",r,new Vector3(side*.12f,.46f,0),new Vector3(.15f,.55f,.15f),Color.white);leg.GetComponent<Renderer>().sharedMaterial=Stone;leg.GetComponent<Renderer>().SetPropertyBlock(null);}var solid=r.gameObject.AddComponent<BoxCollider>();solid.center=new Vector3(0,.85f,0);solid.size=new Vector3(.65f,1.7f,.45f);}
        public static void ThreatVines(Transform t){for(int j=0;j<3;j++){float z=(j-1)*.3f;Tube(t,"CurvedGroundThreatVine",new List<Vector3>{new Vector3(-.7f,.035f,z),new Vector3(-.2f,.10f,z+.12f),new Vector3(.35f,.12f,z-.08f),new Vector3(.7f,.035f,z+.10f)},.035f,Wood);Plant(t,new Vector3((j-1)*.4f,.025f,z),j);}}
        public static void DartWallVisual(Transform root,Vector3 world){var t=Node("DartHolesMountedInActualWall",root,Vector3.zero);t.position=world;Box("StoneDartMount",t,new Vector3(0,1.1f,0),new Vector3(.16f,.38f,.62f),Stone,false);for(int j=0;j<3;j++)Prim.Sphere("SmallDarkWallHole",t,new Vector3(.085f,1.1f,(j-1)*.17f),new Vector3(.012f,.055f,.055f),new Color(.10f,.09f,.055f));}
        static void Decor(Transform t,Vector2 size,int kind){float wx=size.x*.5f,dz=size.y*.5f;for(int j=0;j<6;j++){int side=j%2==0?-1:1;var p=new Vector3(side*(wx-.95f),.022f,-dz*.6f+(j/2)*dz*.52f);Patch(t,p,Vector3.up,.8f,kind+j,Moss);Plant(t,p+new Vector3(-side*.25f,0,.3f),j,kind==1 || kind==6);Vine(t,new Vector3(side*(wx-.18f),3f,p.z),2.6f,kind+j);Patch(t,new Vector3(side*(wx-.16f),.8f,p.z),side<0?Vector3.right:Vector3.left,.75f,j,Moss);}
            if(kind==0 || kind==1)for(int side=-1;side<=1;side+=2)TreeRoot(t,new Vector3(side*(wx-.7f),0,dz*.45f),side+4);
            if(kind==1)for(int j=0;j<10;j++){var p=new Vector3(j%2==0?-3:3,.023f,-3.5f+(j/2)*1.5f);Patch(t,p,Vector3.up,.85f,j,Earth);Plant(t,p,j,true);}
            if(kind==2){for(int side=-1;side<=1;side+=2){Column(t,new Vector3(side*5.5f,0,2.7f),1.6f);TreeRoot(t,new Vector3(side*6.8f,0,2.2f),side+2);}Box("SupportedLowSideBeam",t,new Vector3(0,1.7f,dz-.8f),new Vector3(4.8f,.26f,.24f),Wood);for(int side=-1;side<=1;side+=2)Box("BeamSideSupport",t,new Vector3(side*2.35f,.8f,dz-.8f),new Vector3(.23f,1.6f,.23f),Stone);}
            if(kind==3)for(int j=0;j<4;j++){int side=j%2==0?-1:1;Statue(t,new Vector3(side*(wx-1.6f),0,-2.8f+(j/2)*4.6f),j%2);}
            if(kind==4)for(int side=-1;side<=1;side+=2)for(int j=0;j<3;j++)Column(t,new Vector3(side*3.7f,0,-3.5f+j*3.5f),3.1f);
            if(kind==5){for(int side=-1;side<=1;side+=2){Column(t,new Vector3(side*3.7f,0,-2.8f),side<0?1.4f:2.1f);Column(t,new Vector3(side*3.7f,0,2.8f),2.5f);for(int j=0;j<4;j++){var g=Box("FallenMasonry",t,new Vector3(side*(wx-1.2f),.18f+j*.10f,-2.2f+j*1.4f),new Vector3(.8f,.35f,.7f),Stone);g.transform.localRotation=Quaternion.Euler(0,j*23,8);}}}
            if(kind==6){for(int side=-1;side<=1;side+=2){Column(t,new Vector3(side*3.2f,0,2.5f),2.3f);Plant(t,new Vector3(side*2.6f,0,-1.8f),side,true);}}
        }
    }
}
